// Helper method to remove a node from a doubly-linked list
// Relinks the previous node to the next node
private void removeNode(Node<T> node) {
  Node<T> next = node.next; 
// Reference to next node
  Node<T> prev = node.prev; 
// Reference to previous node
  node.next = null; 
// Unlink the next node
  node.prev = null; 
// Unlink the previous node
  if (prev != null) prev.next=next; // Relink prev node to next
  if (next != null) next.prev=prev; // Relink next node to prev
  if (node == front) front = next; // Adjust the front pointer
  if (node == rear)  rear = prev; 
// Adjust the rear pointer
  count--; 
// Decrement count of nodes
}
