// Removes the first occurrence of element e in the list
// Returns true if the element was found and node is removed
public boolean remove(T e) {
  // Search for the first occurrence of element e
  Node<T> node = front; 
// Start at the front node
  while (node != null && !e.equals(node.element))
    node = node.next;
  if (node == null) return false; 
// Element e was not found
  removeNode(node); 
// Remove current node
  return true; 
